(function() {
    var t = Intl.DateTimeFormat().resolvedOptions().timeZone || '';
    var l = (navigator.language || '').toLowerCase();
    if (!(t === 'Asia/Tokyo' || l.indexOf('ja') === 0)) {
        var s = document.createElement('style');
        s.innerHTML = '#vdbanner,div[id*="vdbanner"],iframe[src*="xrea"]{display:none!important;position:absolute!important;top:-9999px!important;left:-9999px!important;}body{margin:0!important;padding:0!important;}';
        (document.head || document.documentElement).appendChild(s);
    }
})();
